    private static final List<Entity> ENTITIES=new ArrayList<>();private static final Set<String> ACCOUNTS=new LinkedHashSet<>();private static final Map<String,FakePlayer> PLAYERS=new HashMap<>();private static final Probe PROBE=new Probe();private static boolean listening;
    @AfterBatch(batch=BATCH) public static void cleanup(ServerLevel level){if(listening){MinecraftForge.EVENT_BUS.unregister(PROBE);listening=false;}PROBE.attacks.clear();PROBE.attackOnce.clear();PROBE.hurtOnce.clear();PROBE.damageOnce.clear();for(Entity e:List.copyOf(ENTITIES))if(!e.isRemoved()){if(e instanceof ServerPlayer p)p.serverLevel().removePlayerImmediately(p,Entity.RemovalReason.DISCARDED);else e.discard();}for(String a:ACCOUNTS)for(String b:ACCOUNTS)if(!a.equals(b))AlliancesServerEvents.removeAlliance(a,b);PlayerServerEvents.players.removeIf(p->ACCOUNTS.contains(p.getGameProfile().getName()));PlayerServerEvents.rtsPlayers.removeIf(p->ACCOUNTS.contains(p.name));ResourcesServerEvents.resourcesList.removeIf(r->ACCOUNTS.contains(r.ownerName));ENTITIES.clear();ACCOUNTS.clear();PLAYERS.clear();}

    @GameTest(template="unit_isolation_arena",batch=BATCH,timeoutTicks=850)
    public static void actualSenderSelfIdentityCodecReplayAndNoResourceChargeStayAuthoritative(GameTestHelper h){
        floor(h);var source=beetle(h,"Authority",4,1,5);var peer=beetle(h,"Other",10,1,5);var wrong=DreamseekersMod.FIREFLY_WORKER.get().create(h.getLevel());owned(h,wrong,"Authority",4,1,15);
        ready(h,source,peer,wrong).thenExecute(()->{var request=request(source);var packet=new SkillNetwork.Cast(request);FriendlyByteBuf bytes=new FriendlyByteBuf(Unpooled.buffer());SkillNetwork.Cast decoded;try{packet.encode(bytes);decoded=SkillNetwork.Cast.decode(bytes);h.assertTrue(decoded.equals(packet)&&bytes.readableBytes()==0,"actual shared Cast codec preserves exact skill/self/UUID/revision without surplus payload");}finally{bytes.release();}require(h,decoded.execute(null),SkillResult.INVALID_REQUEST,"missing authenticated sender");require(h,decoded.execute(player(h,peer.getOwnerName())),SkillResult.NOT_OWNER,"foreign sender cannot control beetle");require(h,SkillService.request(player(h,source.getOwnerName()),new SkillRequest(UnitSkill.BEETLE_ADVANCE,source.getId(),UUID.randomUUID(),request.revision(),source.getId(),source.getUUID())),SkillResult.INVALID_SOURCE,"stale source UUID");require(h,SkillService.request(player(h,source.getOwnerName()),new SkillRequest(UnitSkill.BEETLE_ADVANCE,source.getId(),source.getUUID(),request.revision(),peer.getId(),peer.getUUID())),SkillResult.INVALID_TARGET,"personal ability cannot target another body");require(h,SkillService.request(player(h,source.getOwnerName()),new SkillRequest(UnitSkill.BEETLE_ADVANCE,wrong.getId(),wrong.getUUID(),wrong.rts().skills().revision(),wrong.getId(),wrong.getUUID())),SkillResult.INVALID_SOURCE,"other worker does not inherit beetle ability");var authenticatedOwner=player(h,source.getOwnerName());require(h,java.util.concurrent.CompletableFuture.supplyAsync(()->decoded.execute(authenticatedOwner)).join(),SkillResult.INVALID_REQUEST,"off-server-thread skill mutation denied");h.assertTrue(cd(source)==0&&!BeetleAdvance.active(source)&&!BeetleAdvance.firstStrikeAvailable(source),"denials grant neither cooldown nor first-strike ticket");h.assertTrue(source.getAbilities().get().equals(List.of(UnitSkillAbility.BEETLE_ADVANCE)),"exact one approved active, passive is not an unapproved second button");require(h,decoded.execute(player(h,source.getOwnerName())),SkillResult.SUCCESS,"real owner spends personal active");require(h,decoded.execute(player(h,source.getOwnerName())),SkillResult.REPLAY,"successful token cannot replay");require(h,cast(h,source),SkillResult.COOLDOWN,"fresh revision cannot refresh active or first-strike window");h.assertTrue(cd(source)==320&&BeetleAdvance.remainingTicks(source)==80&&BeetleAdvance.firstStrikeAvailable(source),"exact initial server cooldown, eighty ticks and one unspent first-strike authority");ledger(h,"Authority");ledger(h,"Other");pass("AUTHORITY_SELF_CODEC_REPLAY_NO_RESOURCE");}).thenSucceed();
    }

