        floor(h);var normal=beetle(h,"First",4,1,5);var boosted=beetle(h,"First",4,1,15);var a=target(h,"FirstEnemy",11,1,5);var b=target(h,"FirstEnemy",11,1,15);var bone=bone(h,"First",7,2,12);
